    # 0이 하나인 경우(5개)와 1이 하나인 경우(5개)만 테스트
    test_cases = [[1 if i != k else 0 for i in range(5)] for k in range(5)] + \
                 [[0 if i != k else 1 for i in range(5)] for k in range(5)]
    for v in test_cases:
        curr = list(v)
        for i, j in net:
            if curr[i] > curr[j]: curr[i], curr[j] = curr[j], curr[i]
        if any(curr[t] > curr[t+1] for t in range(4)): return False
    return True

