def judge(x):
    if not isinstance(x, dict) or 'network' not in x or 'witness' not in x:
        raise ValueError('형식 오류')
    net_data = x['network']
    witness = x['witness']
    if not isinstance(net_data, list) or len(net_data) != 7:
        raise ValueError('네트워크 형식 오류')
    net = []
    for c in net_data:
        if not isinstance(c, dict) or 'gate' not in c:
            raise ValueError('게이트 형식 오류')
        i, j = int(c['gate'][0]), int(c['gate'][1])
        if not (0 <= i < j < 5):
            raise ValueError('게이트 범위 오류')
        net.append((i, j))
    if not isinstance(witness, list) or len(witness) != 32:
        raise ValueError('증인 형식 오류')

    for item in witness:
        if not isinstance(item, dict) or 'input' not in item or 'trace' not in item:
            raise ValueError('증인 항목 오류')
        inp = item['input']
        trace = item['trace']
        if len(trace) != len(net) + 1:
            return False
        if trace[0] != inp:
            return False
        curr = list(inp)
        for idx, (i, j) in enumerate(net):
            if curr[i] > curr[j]:
                curr[i], curr[j] = curr[j], curr[i]
            if trace[idx+1] != curr:
                return False
        if any(curr[t] > curr[t+1] for t in range(4)):
            return False
    return True

