    if not isinstance(x, (tuple, list)) or len(x) != 3:
        raise ValueError('형식 오류')
    net, bits, out_v = x
    if len(net) != 9:
        raise ValueError('비교기 9개 아님')
    if not isinstance(bits, int) or not (0 <= bits < 32):
        raise ValueError('비트 오류')
    if not isinstance(out_v, list) or len(out_v) != 5 or not all(b in (0, 1) for b in out_v):
        raise ValueError('출력 상태 오류')
    for i, j in net:
        if not (0 <= i < 5 and 0 <= j < 5):
            raise ValueError('범위 오류')
    v = [(bits >> t) & 1 for t in range(5)]
    for i, j in net:
        if v[i] > v[j]: v[i], v[j] = v[j], v[i]
    if v != out_v:
        return False
    return any(out_v[t] > out_v[t+1] for t in range(4))

problems.옮김:
def embed(x):
    net, bits = x
    v = [(bits >> t) & 1 for t in range(5)]
    for i, j in net:
        if v[i] > v[j]: v[i], v[j] = v[j], v[i]
    return (net, bits, v)

