problems.판정:
def judge(x):
    import json
    if not isinstance(x, str):
        raise ValueError('문자열 아님')
    try:
        data = json.loads(x)
    except Exception:
        raise ValueError('JSON 파싱 오류')
    if not isinstance(data, dict) or 'net' not in data or 'bits' not in data:
        raise ValueError('필드 오류')
    net = data['net']
    bits = data['bits']
    if not isinstance(net, list) or len(net) != 9:
        raise ValueError('비교기 9개 아님')
    if not isinstance(bits, int) or not (0 <= bits < 32):
        raise ValueError('비트 오류')
    v = [(bits >> t) & 1 for t in range(5)]
    for c in net:
        if not isinstance(c, list) or len(c) != 2 or not (0 <= c[0] < 5 and 0 <= c[1] < 5):
            raise ValueError('범위 오류')
        i, j = c
        if v[i] > v[j]: v[i], v[j] = v[j], v[i]
    return any(v[t] > v[t+1] for t in range(4))

